-- 任职接口测试用的隔离表结构与种子数据；仅在本机测试库执行。
DROP TABLE IF EXISTS public.pos_position_assignments CASCADE;
DROP TABLE IF EXISTS public.pos_positions CASCADE;

CREATE TABLE public.pos_positions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar NOT NULL,
  level varchar NOT NULL DEFAULT '',
  category varchar NOT NULL DEFAULT '',
  status smallint NOT NULL DEFAULT 0,
  review_status varchar NOT NULL DEFAULT 'unreviewed',
  business_tenant_id bigint NOT NULL
);

CREATE TABLE public.pos_position_assignments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  position_id bigint NOT NULL REFERENCES public.pos_positions (id),
  user_id bigint NOT NULL,
  project_id bigint,
  role_in_project varchar NOT NULL,
  start_date date,
  end_date date,
  is_primary boolean NOT NULL DEFAULT true,
  status smallint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  source_bucket varchar NOT NULL DEFAULT '',
  source_object_key text NOT NULL DEFAULT '',
  source_sheet varchar NOT NULL DEFAULT '',
  source_row_no integer,
  ingestion_batch_id bigint,
  review_status varchar NOT NULL DEFAULT 'unreviewed',
  business_tenant_id bigint NOT NULL
);

